import React, { useState } from "react";
import api from "../api";

export default function Contact(){
  const [form, setForm] = useState({ name:"", email:"", phone:"", message:"" });
  const [status, setStatus] = useState("");

  const change = e => setForm(f=>({...f,[e.target.name]:e.target.value}));

  const submit = async (e) => {
    e.preventDefault();
    setStatus("Sending...");
    try {
      await api.post("/contact", form);
      setStatus("Message sent. Thank you!");
      setForm({ name:"", email:"", phone:"", message:"" });
    } catch (err) {
      setStatus("Send failed.");
    }
  };

  return (
    <div className="container card">
      <h2>Contact Us</h2>
      <div className="two-col">
        <div className="left">
          <form onSubmit={submit}>
            <input name="name" placeholder="Your Name" value={form.name} onChange={change} required/>
            <input name="email" placeholder="Your Email" value={form.email} onChange={change} required/>
            <input name="phone" placeholder="Phone" value={form.phone} onChange={change}/>
            <textarea name="message" placeholder="Message" value={form.message} onChange={change} required/>
            <button type="submit">Send</button>
            <div>{status}</div>
          </form>
        </div>
        <div className="right">
          <h3>Contact Info</h3>
          <p>Address: Near Gandhi Institute...</p>
          <p>Phone: +91 9045032868</p>
          <p>Email: <a href="mailto:gipsmrt.in@gmail.com">gipsmrt.in@gmail.com</a></p>
        </div>
      </div>
    </div>
  );
}
